module.exports = grammar({
  name: 'test_lang',
  rules: {
    source_file: $ => repeat($.statement),
    statement: $ => choice(
      $.expression,
      $.comment
    ),
    expression: $ => /[a-zA-Z_][a-zA-Z0-9_]*/,
    comment: $ => /#.*/
  }
});
